<script lang="ts">
  import { page } from '$app/state';
  import Icon from '$lib/components/Icon.svelte';
  import { getAsset } from '$lib/data/marketplace';
  import { buyerOrders, createSupportTicket, supportTickets } from '$lib/stores/buyer';
  let formOpen=Boolean(page.url.searchParams.get('product'));
  let subject=''; let category:'Asset support'|'Order & billing'|'Account'='Asset support';
  let productSlug=page.url.searchParams.get('product') ?? '';
  let orderId=page.url.searchParams.get('order') ?? '';
  let message=''; let filter='All';
  $: products=[...new Set($buyerOrders.flatMap((order)=>order.items.map((item)=>item.slug)))].flatMap((slug)=>{const asset=getAsset(slug);return asset?[asset]:[]});
  $: filtered=$supportTickets.filter((ticket)=>filter==='All'||ticket.status===filter);
  function submit(){if(subject.trim()&&message.trim()){createSupportTicket({subject:subject.trim(),category,productSlug:productSlug||undefined,orderId:orderId||undefined,message:message.trim()});formOpen=false;subject='';message='';}}
</script>
<svelte:head><title>Buyer support — AssetGuru</title></svelte:head>
<header class="page-head"><div><span class="eyebrow">Buyer protection</span><h1>Support <span class="gradient-text">centre.</span></h1><p>Contact the right creator with product and version context, or ask AssetGuru about orders, billing and account issues.</p></div><button class="button button-primary" type="button" onclick={()=>formOpen=true}><Icon name="plus" size={18}/> New support ticket</button></header>
<div class="support-grid">
  <section class="tickets glass"><div class="panel-head"><div><span class="eyebrow">Your cases</span><h2>Support tickets</h2></div><select bind:value={filter}><option>All</option><option>Open</option><option>Waiting on creator</option><option>Resolved</option></select></div>{#each filtered as ticket}<article class="ticket"><i class:resolved={ticket.status==='Resolved'}><Icon name={ticket.category==='Refund request'?'tag':'support'} size={19}/></i><div><div class="ticket-head"><span><b>{ticket.subject}</b><small>{ticket.id} · {ticket.category}</small></span><em class:resolved={ticket.status==='Resolved'}>{ticket.status}</em></div><p>{ticket.message}</p><div class="context">{#if ticket.productSlug&&getAsset(ticket.productSlug)}<a href={`/marketplace/${ticket.productSlug}`}>{getAsset(ticket.productSlug)?.title}</a>{/if}{#if ticket.orderId}<a href={`/account/orders/${ticket.orderId}`}>Order {ticket.orderId}</a>{/if}<span>Updated {ticket.updated}</span></div></div></article>{:else}<div class="empty"><Icon name="check" size={38}/><h3>No tickets in this view.</h3></div>{/each}</section>
  <aside><section class="routing glass"><span class="eyebrow">Smart routing</span><h2>Who handles what?</h2><div><Icon name="store" size={21}/><span><b>Creator support</b><small>Installation, asset setup, compatibility and product-specific questions.</small></span></div><div><Icon name="shield" size={21}/><span><b>AssetGuru support</b><small>Payments, refunds, licences, account access and marketplace conduct.</small></span></div></section><section class="promise glass"><Icon name="clock" size={27}/><h3>Clear response targets</h3><p>Verified creators show their typical response time. AssetGuru billing and account requests are prioritised separately.</p><a href="/support">Browse public help →</a></section></aside>
</div>
{#if formOpen}<div class="modal-backdrop" role="presentation" onclick={(event)=>{if(event.target===event.currentTarget)formOpen=false;}}><form class="modal glass" onsubmit={(event)=>{event.preventDefault();submit();}}><button class="close" type="button" onclick={()=>formOpen=false}><Icon name="close" size={18}/></button><span class="eyebrow">New case</span><h2>How can we help?</h2><div class="two"><label>Category<select bind:value={category}><option>Asset support</option><option>Order & billing</option><option>Account</option></select></label><label>Related product<select bind:value={productSlug}><option value="">No product selected</option>{#each products as asset}<option value={asset.slug}>{asset.title}</option>{/each}</select></label></div><label>Related order<select bind:value={orderId}><option value="">No order selected</option>{#each $buyerOrders as order}<option value={order.id}>{order.id} · {order.date}</option>{/each}</select></label><label>Subject<input bind:value={subject} required maxlength="100" placeholder="Describe the issue briefly"/></label><label>Message<textarea bind:value={message} required minlength="20" placeholder="Include what you expected, what happened and any steps already tried."></textarea></label><button class="button button-primary" type="submit">Create ticket</button></form></div>{/if}
