  @media(max-width:900px){.support-grid{grid-template-columns:1fr}}@media(max-width:620px){.page-head{align-items:start;flex-direction:column}.ticket-head{align-items:start;flex-direction:column;gap:7px}.two{grid-template-columns:1fr}}
